{
  "references": [
    {
      "id": "R1",
      "summary_ko": "흙이 움직임에 반응하지 않고 사람의 손 정렬이 어긋나며, 카메라가 위로 표류하고 조명이 저녁으로 바뀜."
    },
    {
      "id": "R2",
      "summary_ko": "프롬프트의 팀 묘사와 달리 말이 두 마리만 등장하여 프롬프트가 잘못 재현됨."
    },
    {
      "id": "R3",
      "summary_ko": "사람이 아무런 작업도 하지 않아 말과 함께 체계적으로 일하고 있다고 볼 수 없음."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "말들의 다리와 끌리는 쟁기 장치가 비자연스러운 왜곡, 녹아내리는 움직임 및 불안정한 지면 접촉을 보임."
    },
    {
      "id": "C2",
      "summary_ko": "왼쪽 말의 꼬리가 다리와 반복적으로 겹쳐지며 흔들릴 때 형태가 일관되지 않게 변함."
    },
    {
      "id": "C3",
      "summary_ko": "말 뒤의 수레/쟁기 구조물이 기계적 강성을 유지하지 못하고 미세하게 형태가 변형됨."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R1은 흙 반응 부재, 손 정렬 불량, 카메라 움직임 및 조명 변화를 지적하는 반면 C1은 말 다리와 쟁기의 왜곡 및 불안정한 지면 접촉을 지적하여 대상과 현상이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 흙, 손, 카메라, 조명의 이상을 다루지만 C2는 왼쪽 말의 꼬리 클리핑 현상을 다루므로 서로 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R1은 환경적/인물 관련 이상을 설명하고 C3은 수레/쟁기 구조물의 형태 모핑을 설명하므로 대상과 결함이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R2는 말의 개체 수에 대한 프롬프트 불일치를 다루는 반면 C1은 말 다리와 쟁기의 물리적 왜곡을 다룹니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R2는 말의 수량에 대한 내용이고 C2는 말 꼬리의 클리핑 및 형태 변형에 대한 내용입니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R2는 말의 개체 수 불일치에 관한 것이며 C3은 쟁기 구조물의 형태 변형에 관한 것입니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R3은 사람이 일을 하지 않는 행동 결함을 설명하는 반면 C1은 말 다리와 쟁기의 왜곡 현상을 설명합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R3은 사람의 작업 부재를 다루고 C2는 말 꼬리의 물리적 클리핑을 다룹니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R3은 인물의 행동 결함을 지적하고 C3은 쟁기 구조물의 형태 불안정성을 지적합니다."
    }
  ]
}
